{"code": "import pandas as pd, numpy as np
import statsmodels.formula.api as smf
df = pd.read_csv('data/explore.csv')
exposures = ['nitrogen_ppm','phosphorus_ppm','potassium_ppm','soil_ph','irrigation_mm','seed_density','mulch_depth_cm','biochar_g','fungicide_ml','shade_pct']
d = df.dropna(subset=['yield_kg']).copy()
rng = np.random.default_rng(0)
res = {e:[] for e in exposures}
for b in range(2000):
    s = d.sample(len(d), replace=True, random_state=b)
    m = smf.ols('yield_kg ~ ' + ' + '.join(exposures) + ' + C(farm)', data=s).fit()
    for e in exposures:
        res[e].append(m.params[e])
for e in exposures:
    a = np.array(res[e])
    print(f"{e:18s} mean={a.mean():7.4f} sd={a.std():6.4f} frac>0={np.mean(a>0):.3f}")
"}
